    step("__html__ 方法:带 __html__ 的对象在模板里被当作安全 HTML:Widget('<保存>') 的 __html__ 返回 Markup('<button>{}</button>').format(label),{{ w }} 输出 <button>&lt;保存&gt;</button>(标签保留、标签内文字被转义);{{ w|string }} 走 __str__ 得到 Widget(&lt;保存&gt;);{{ [w]|join(\",\") }} 也使用 __html__。", t=tl(S(4)), done=lidx(S(4), '{{ w }}'), kv=KV([['{{ w }}', '调用 __html__'], ['|string', '调用 __str__']], ['{{ w }}'])),
    step("把字符串变成 Markup 的几种写法对同一个恶意输入 \"><img src=x onerror=alert(1)> 的结果:Markup(f'<a title=\"{u}\">') 危险(<img> 标签原样出现);Markup('<a title=\"{}\">').format(u)、Markup('<a title=\"%s\">') % u、Markup('<a title=\"') + u + Markup('\">') 都安全(输入被转义);'<a title=\"' + escape(u) + '\">'(左边是普通 str)整个结果会被转义成文本,同样没有执行风险,但标签也变成了文字。", t=tl(S(5)), mark=lidx(S(5), '危险'), done=lidx(S(5), 'format(u)', '% u', '+ u +'), kv=KV([['Markup(f\"…{u}…\")', '危险'], ['Markup(…).format(u) / % u', '安全'], ['str + escape(u)', '整体被转义成文字']], ['Markup(f\"…{u}…\")'])),
    step("striptags 与 unescape:Markup('<p>a &amp; <b>b</b></p>').striptags() → 'a & b'(去标签并还原实体,返回普通 str);Markup('&lt;b&gt;').unescape() → '<b>'(把实体还原成字符,返回普通 str)。这两个方法的结果不再是「安全」的,输出到页面前仍需转义。", t=tl(S(6)), done=lidx(S(6), 'striptags()'), kv=KV([['striptags()', "'a & b'(str)"], ['unescape()', "'<b>'(str)"]], ['unescape()'])),
